CREATE OR REPLACE FUNCTION public.can_read_party_contact(_party uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_permission('customers.contacts','view') OR (public.has_permission('customers.contacts','own') AND EXISTS(SELECT 1 FROM public.opportunities WHERE party_id=_party AND owner_user_id=auth.uid() AND outcome IS NULL)) $$;
REVOKE ALL ON FUNCTION public.can_read_party_contact(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.can_read_party_contact(uuid) TO authenticated;
CREATE OR REPLACE VIEW public.parties_crm AS SELECT p.id,p.tenant_code,p.party_type,p.name_ar,p.name_en,p.city,p.source,p.tenant_lifecycle,p.created_at,p.archived_at,CASE WHEN public.can_read_party_contact(p.id) THEN p.phone ELSE NULL END AS phone,CASE WHEN public.can_read_party_contact(p.id) THEN p.email ELSE NULL END AS email,CASE WHEN public.can_read_party_contact(p.id) THEN p.id_type ELSE NULL END AS id_type,CASE WHEN public.can_read_party_contact(p.id) THEN p.id_number ELSE NULL END AS id_number FROM public.parties p WHERE public.has_permission('customers.names','view');
CREATE POLICY party_contact_permission_gate ON public.party_contacts AS RESTRICTIVE FOR SELECT TO authenticated USING(public.can_read_party_contact(party_id));
CREATE POLICY opportunities_permission_read ON public.opportunities AS RESTRICTIVE FOR SELECT TO authenticated USING(public.has_permission('opportunities.read','view'));
REVOKE INSERT,UPDATE,DELETE ON public.opportunities,public.parties FROM authenticated,anon;
CREATE OR REPLACE FUNCTION public.assign_opportunity(_opportunity_id uuid,_to_user uuid,_reason text) RETURNS public.opportunities LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oldrow public.opportunities;newrow public.opportunities;BEGIN IF NOT public.has_permission('opportunities.assign','edit') THEN RAISE EXCEPTION 'إعادة التوزيع غير مسموحة';END IF;PERFORM public._assert_reason(_reason);IF NOT public.has_role(_to_user,'sales_agent') THEN RAISE EXCEPTION 'اختر وسيطًا فعالًا';END IF;SELECT * INTO oldrow FROM public.opportunities WHERE id=_opportunity_id FOR UPDATE;IF NOT FOUND OR oldrow.outcome IS NOT NULL OR oldrow.stage='won' THEN RAISE EXCEPTION 'الفرصة غير موجودة أو مغلقة';END IF;UPDATE public.opportunities SET owner_user_id=_to_user,updated_at=now() WHERE id=oldrow.id RETURNING * INTO newrow;INSERT INTO public.opportunity_owner_history(opportunity_id,from_owner,to_owner,reason,actor_id) VALUES(oldrow.id,oldrow.owner_user_id,_to_user,_reason,auth.uid());PERFORM public._safety_audit('OPPORTUNITY_ASSIGNED','opportunities',oldrow.id::text,to_jsonb(oldrow),to_jsonb(newrow),_reason);RETURN newrow;END $$;
DO $$ DECLARE f record;d text;guard text;BEGIN FOR f IN SELECT p.oid,p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN('move_opportunity','log_opportunity_activity','create_opportunity','create_party','bulk_reassign_opportunities') AND p.prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql') LOOP d:=pg_get_functiondef(f.oid);guard:=CASE WHEN f.proname='bulk_reassign_opportunities' THEN 'IF NOT public.has_permission(''opportunities.assign'',''edit'') THEN RAISE EXCEPTION ''غير مسموح بإعادة التوزيع''; END IF;' WHEN f.proname='create_party' THEN 'IF NOT(public.has_permission(''opportunities.write'',''edit'') OR public.has_permission(''opportunities.write'',''own'')) THEN RAISE EXCEPTION ''غير مسموح بإنشاء العميل''; END IF;' ELSE 'IF NOT(public.has_permission(''opportunities.write'',''edit'') OR public.has_permission(''opportunities.write'',''own'')) THEN RAISE EXCEPTION ''غير مسموح بتعديل الفرص''; END IF;' END;IF position(guard IN d)=0 THEN d:=regexp_replace(d,'\mBEGIN\M','BEGIN '||guard,'i');EXECUTE d;END IF;END LOOP;END $$;
SELECT to_regprocedure('public.can_read_party_contact(uuid)') IS NOT NULL AS contact_gate_ready,has_table_privilege('authenticated','public.opportunities','UPDATE') AS direct_update_must_be_false;